// ---- The three closure traits ----

// ---- Fn: called multiple times, no mutation ----
fn call_fn<F: Fn(i32) -> i32>(f: F, x: i32) -> i32 {
    f(f(x))
}

// ---- FnMut: called multiple times, can mutate ----
fn call_fn_mut<F: FnMut(i32) -> i32>(mut f: F, x: i32) -> i32 {
    f(f(x))
}

// ---- FnOnce: called once, takes ownership ----
fn call_fn_once<F: FnOnce(i32) -> i32>(f: F, x: i32) -> i32 {
    f(x)
}

// ---- Examples of each ----
fn main() {
    // ---- Fn: no mutation, borrows ----
    let multiplier = 2;
    let double = |x| x * multiplier;

    println!("Fn: double(5) = {}", double(5));
    let result = call_fn(double, 5);
    println!("call_fn(double, 5) = {}", result);

    // ---- FnMut: mutates captured variables ----
    let mut count = 0;
    let mut increment = || {
        count += 1;
        count
    };

    println!("FnMut: increment() = {}", increment());
    println!("FnMut: increment() = {}", increment());

    // ---- FnOnce: takes ownership ----
    let name = String::from("Hero");
    let consume = || {
        drop(name);
        println!("Name consumed!");
    };

    // consume() can only be called once
    consume();

    // ---- Function that takes FnOnce ----
    let data = String::from("Hello");
    let mut closure = move || {
        println!("Data: {}", data);
    };
    closure();  // Works because FnOnce can be called once

    // ---- FnOnce with move ----
    let items = vec!["Sword", "Shield"];
    let consume_items = move || {
        println!("Items: {:?}", items);
    };
    consume_items();

    // ---- Comparing the traits ----
    // Fn: called multiple times, no mutation
    // FnMut: called multiple times, can mutate
    // FnOnce: called once, takes ownership

    // ---- Fn and FnMut can be used as FnOnce ----
    let add = |a, b| a + b;  // Fn
    let result = call_fn_once(add, 5);
    println!("Fn as FnOnce: {}", result);
}

// ---- Function that takes FnMut ----
fn apply_twice_mut<F: FnMut(i32) -> i32>(mut f: F, x: i32) -> i32 {
    let y = f(x);
    f(y)
}

fn main2() {
    let mut multiplier = 2;
    let mut double_mut = |x| {
        multiplier += 1;
        x * multiplier
    };

    let result = apply_twice_mut(double_mut, 5);
    println!("apply_twice_mut: {}", result);
}

